#include <Adafruit_NeoPixel.h>
Adafruit_NeoPixel strip({{num_pixels}}, {{data_pin}}, NEO_GRB + NEO_KHZ800);
const int BTN = {{button_pin}};
uint32_t colors[] = {0xFF0000, 0x00FF00, 0x0000FF, 0xFFFFFF};
int idx = 0;
int last = HIGH;

void setup() {
  strip.begin();
  pinMode(BTN, INPUT_PULLUP);
}

void loop() {
  int r = digitalRead(BTN);
  if (last == HIGH && r == LOW) {
    idx = (idx + 1) % 4;
    strip.fill(colors[idx]); strip.show();
    delay(150);
  }
  last = r;
}
